#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/run.py" ] || echo "WARNING: submission missing: /home/workspace/run.py"
[ -e "/home/workspace/main.py" ] || echo "WARNING: submission missing: /home/workspace/main.py"
[ -e "/home/workspace/config.json" ] || echo "WARNING: submission missing: /home/workspace/config.json"
[ -e "/home/workspace/config.yaml" ] || echo "WARNING: submission missing: /home/workspace/config.yaml"
[ -e "/home/workspace/nav_history.csv" ] || echo "WARNING: submission missing: /home/workspace/nav_history.csv"
[ -e "/home/workspace/signal_matrix.csv" ] || echo "WARNING: submission missing: /home/workspace/signal_matrix.csv"
[ -e "/home/workspace/positions.csv" ] || echo "WARNING: submission missing: /home/workspace/positions.csv"
[ -e "/home/workspace/trades.csv" ] || echo "WARNING: submission missing: /home/workspace/trades.csv"
[ -e "/home/workspace/risk_budget_allocation.csv" ] || echo "WARNING: submission missing: /home/workspace/risk_budget_allocation.csv"
[ -e "/home/workspace/performance_report.md" ] || echo "WARNING: submission missing: /home/workspace/performance_report.md"
[ -e "/home/workspace/performance_report.xlsx" ] || echo "WARNING: submission missing: /home/workspace/performance_report.xlsx"
[ -e "/home/workspace/stress_test_report.md" ] || echo "WARNING: submission missing: /home/workspace/stress_test_report.md"
[ -e "/home/workspace/stress_test_results.xlsx" ] || echo "WARNING: submission missing: /home/workspace/stress_test_results.xlsx"
[ -e "/home/workspace/sensitivity_analysis_report.md" ] || echo "WARNING: submission missing: /home/workspace/sensitivity_analysis_report.md"
[ -e "/home/workspace/sensitivity_analysis.xlsx" ] || echo "WARNING: submission missing: /home/workspace/sensitivity_analysis.xlsx"
[ -e "/home/workspace/diagnostics.json" ] || echo "WARNING: submission missing: /home/workspace/diagnostics.json"
[ -e "/home/workspace/outputs" ] || echo "WARNING: submission missing: /home/workspace/outputs"

cd /home/workspace
OUT=$(cd /home/workspace && python3 scoring/score.py 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
